import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"初始面板","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/startup-panel.md","filePath":"zh-HK/user-guide/settings/startup-panel.md","lastUpdated":1785587987000}'),s={name:"zh-HK/user-guide/settings/startup-panel.md"};function n(l,t,i,u,d,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="初始面板" tabindex="-1">初始面板 <a class="header-anchor" href="#初始面板" aria-label="Permalink to &quot;初始面板&quot;">​</a></h1><p>搜尋框為空時，快速視窗結果列表上方顯示的一個標籤欄，不用輸入查詢就能快速訪問最近檔案、收藏夾和歷史記錄。</p><ul><li><strong>啓用初始面板</strong> —— 總開關;關閉後，不管下面各個標籤自己的設定如何，整個面板都不會激活。</li></ul><p>四個子標籤:<strong>最近檔案</strong>、<strong>上次目錄</strong>、<strong>插件標籤</strong> 和 <strong>標籤順序</strong>。</p><h2 id="最近檔案" tabindex="-1">最近檔案 <a class="header-anchor" href="#最近檔案" aria-label="Permalink to &quot;最近檔案&quot;">​</a></h2><ul><li><strong>啓用面板</strong> —— 勾選框;搜尋框為空時顯示該標籤。</li><li><strong>目錄</strong> —— 要監控的資料夾，每行一個(添加/編輯/刪除單行，以及批量文本編輯，和<a href="./index-drives.html#排除規則">排除規則列表</a>是同一套交互)。可以是本地磁碟機、已掛載的網絡磁碟機，以及 WSL 路徑(<code>\\\\wsl$\\...</code> 或 <code>\\\\wsl.localhost\\...</code>)——會匹配到你已經在<a href="./index-drives.html">索引</a>裏配置並建過索引的對應條目。</li><li><strong>顯示的檔案數量上限</strong> —— 範圍 1–100，預設 10。</li><li><strong>時間範圍(分鐘)</strong> —— 只有在這個時間範圍內修改過的檔案才符合條件，疊加在上面的數量上限之上。範圍 1–43200(30 天)，預設 60。</li></ul><p>只列檔案，不列資料夾：往一個資料夾裏加東西、刪東西都會刷新它自己的修改時間，所以正在用的目錄裏，資料夾總是「最新」的那幾個，會把這份清單本來要顯示的東西擠下去。</p><p>每一項的第二行開頭會帶上一個相對時間——&quot;X 秒/分鐘/小時/天前&quot;——直接根據索引裏已經存好的檔案最後修改時間算出來，不需要額外訪問磁碟。小時和天這兩檔在餘下的分鐘/小時為 0 時會省略(比如顯示 &quot;2小時前&quot;而不是&quot;2小時0分鐘前&quot;)。</p><h2 id="上次目錄" tabindex="-1">上次目錄 <a class="header-anchor" href="#上次目錄" aria-label="Permalink to &quot;上次目錄&quot;">​</a></h2><ul><li><strong>啓用面板</strong> —— 勾選框，預設開啓。</li></ul><p>顯示 SwiftList 接管系統檔案打開/保存對話方塊時，最後停留過的目錄內容——不用記路徑，就能快速回到剛才用檔案選擇器瀏覽過的地方。真正的索引會用到的隱藏/系統檔案過濾和<a href="./index-drives.html#排除規則">排除規則</a>在這裏同樣生效，所以不會出現 <code>$RECYCLE.BIN</code> 這類東西。本次運行還沒有觸發過、該目錄已經不存在、或者就是桌面(經常只是預設落腳點，不算真的&quot;去過&quot;)時，這個標籤完全不會出現。</p><h2 id="插件標籤" tabindex="-1">插件標籤 <a class="header-anchor" href="#插件標籤" aria-label="Permalink to &quot;插件標籤&quot;">​</a></h2><p>插件提供的標籤(如歷史記錄、收藏夾)在面板裏各自帶一個 <strong>×</strong> 按鈕，可以先把它隱藏起來。這只是面板本地的&quot;先不顯示&quot;選擇——和在<a href="./plugins.html">插件</a>頁面裏把該插件組件本身禁用是兩回事，後者是讓它徹底不參與使用。通過 × 關閉的標籤會按提供它的插件分組顯示在這裏，未勾選;勾上即可重新打開。</p><p>只有插件層面已啓用的標籤才會出現在這個列表裏——在<a href="./plugins.html">插件</a>頁面整體禁用的組件，從一開始就不會成為候選標籤。</p><h2 id="標籤順序" tabindex="-1">標籤順序 <a class="header-anchor" href="#標籤順序" aria-label="Permalink to &quot;標籤順序&quot;">​</a></h2><p>跟設定裏其它地方(見<a href="./favorites.html">收藏夾</a>)同一套上移/下移(也可以拖動)排序列表，但管的是整個面板標籤欄—— 內置的兩個標籤(最近檔案、上次目錄)和所有當前可見的插件標籤都在同一個扁平列表裏，跟上面按插件分組的&quot;插件標籤&quot;不一樣。把某個標籤上移或下移，就能改變它在實際面板裏的位置；這個列表裏從上到下的順序，對應面板裏從左到右的順序。</p><p>這裏只列出當前真的會顯示出來的標籤——上面被關掉的&quot;最近檔案&quot;/&quot;上次目錄&quot;，或者用 <strong>×</strong> 按鈕關閉過的插件標籤，在重新啓用/重新打開之前都沒有順序可調。</p>',17)])])}const c=a(s,[["render",n]]);export{g as __pageData,c as default};
